<script>
(() => { const list = document.getElementById('source-list'); const add = document.getElementById('add-source'); const template = document.getElementById('source-template'); const sync = () => { const rows = [...list.querySelectorAll('.source-row')]; rows.forEach((row) => row.querySelector('.remove-source').classList.toggle('hidden', rows.length === 1)); add.disabled = rows.length >= 8; add.classList.toggle('opacity-50', add.disabled); }; add.addEventListener('click', () => { if (list.querySelectorAll('.source-row').length < 8) { list.append(template.content.cloneNode(true)); sync(); } }); list.addEventListener('click', (event) => { if (event.target.closest('.remove-source')) { event.target.closest('.source-row').remove(); sync(); } }); sync(); })();
</script>
